def _v321_rewrite_path(value, bundle_root, input_path, outputs, stage_tmp):
    # Exact selected prior submissions become runtime-generated intermediates.
    for ref_dir, actual_dir in outputs.get("dirs", {}).items():
        if value == ref_dir or value.startswith(ref_dir + "/"):
            suffix = value[len(ref_dir):].lstrip("/")
            return str(_V321Path(actual_dir) / suffix) if suffix else actual_dir
    for ref, actual in outputs.get("files", {}).items():
        if value == ref:
            return actual
    if value in ("data/materialized/dev/inputs.json", "data/dev/inputs.json", "data/train/inputs.json"):
        return str(input_path)
    if value.startswith("build/") or value.startswith("configs/") or value.startswith("baselines/") or value.startswith("experiments/"):
        return str(_V321Path(bundle_root) / value)
    return value


def _v321_run_stage(stage, bundle_root, input_path, outputs, work_root, tier):
    stage_tmp = _V321Path(work_root) / stage["name"]
    stage_tmp.mkdir(parents=True, exist_ok=True)
    argv = []
    skip_next = False
    output_dir = None
    output_file = None
    report_file = None
    original = list(stage["argv"])
    i = 0
    while i < len(original):
        token = original[i]
        # Historical run scripts use shell variables such as $TIER.  The
        # manifest stores argv before shell-loop expansion, so resolve the
        # selected tier explicitly at runtime.
        if token in ("$TIER", "${TIER}"):
            argv.append(tier); i += 1; continue
        if token in ("--input",):
            argv.extend([token, str(input_path)]); i += 2; continue
        if token == "--config":
            argv.extend([token, _v321_rewrite_path(original[i+1], bundle_root, input_path, outputs, stage_tmp)]); i += 2; continue
        if token in ("--output-dir", "--submissions"):
            output_dir = str(stage_tmp / "submissions")
            _V321Path(output_dir).mkdir(parents=True, exist_ok=True)
            argv.extend([token, output_dir]); i += 2; continue
        if token == "--output":
            output_file = str(stage_tmp / f"{tier}.json")
            argv.extend([token, output_file]); i += 2; continue
        if token in ("--report", "--swap-report"):
            report_file = str(stage_tmp / "report.json")
            argv.extend([token, report_file]); i += 2; continue
        if i + 1 < len(original) and token.startswith("--"):
            value = original[i+1]
            value = value.replace("${TIER}", tier).replace("$TIER", tier)
            argv.extend([token, _v321_rewrite_path(value, bundle_root, input_path, outputs, stage_tmp)])
            i += 2; continue
        token = token.replace("${TIER}", tier).replace("$TIER", tier)
        argv.append(_v321_rewrite_path(token, bundle_root, input_path, outputs, stage_tmp)); i += 1

    script = str(_V321Path(bundle_root) / stage["source_script"])
    dirs = sorted({str((_V321Path(bundle_root) / p).parent) for p in _V321_MANIFEST["files"] if p.endswith(".py")})
    env = dict(_v321_os.environ)
    # The dry-run launcher starts from the repository root with PYTHONPATH=src.
    # Child stages run with cwd=bundle_root; passing that relative entry through
    # unchanged would make it point at bundle_root/src and hide ossp_router.
    # Resolve inherited entries against the current parent cwd before changing
    # the child's cwd.  In the final container /opt/router remains the primary
    # package root.
    inherited = []
    for item in env.get("PYTHONPATH", "").split(_v321_os.pathsep):
        if item:
            inherited.append(str(_V321Path(item).resolve()))
    live_src = str(_V321Path(__file__).resolve().parent.parent)
    env["PYTHONPATH"] = _v321_os.pathsep.join([live_src, str(bundle_root), *dirs, *inherited])
    cp = _v321_subprocess.run([_v321_sys.executable, script, *argv], cwd=bundle_root, env=env, text=True, stdout=_v321_subprocess.PIPE, stderr=_v321_subprocess.PIPE)
    if cp.returncode != 0:
        raise RuntimeError(f"V32.1c stage {stage['name']} failed rc={cp.returncode} stdout={cp.stdout[-2000:]} stderr={cp.stderr[-4000:]}")

    # Locate generated selected submission(s) and register their reference path mapping.
    ref_dir = stage["reference_dir"]
    if output_dir is not None:
        actual_dir = output_dir
    elif output_file is not None:
        actual_dir = str(_V321Path(output_file).parent)
    else:
        raise RuntimeError(f"V32.1c stage {stage['name']} has no output target")
    outputs.setdefault("dirs", {})[ref_dir] = actual_dir
    for ref_tier, ref in stage.get("reference_files", {}).items():
        if ref_tier == tier and output_file is not None:
            candidate = _V321Path(output_file)
        else:
            candidate = _V321Path(actual_dir) / f"{ref_tier}.json"
        if candidate.is_file():
            outputs.setdefault("files", {})[ref] = str(candidate)
    return outputs


def _v321_generate(input_path, tier, output_path):
    from ossp_router.protocol import load_json, parse_submission
    input_path = _V321Path(input_path).resolve()
    with _v321_tempfile.TemporaryDirectory(prefix="v321-runtime-", dir="/tmp") as td:
        root = _V321Path(td)
        bundle = root / "bundle"; bundle.mkdir()
        work = root / "work"; work.mkdir()
        _v321_extract(bundle)
        outputs = {"dirs": {}, "files": {}}
        for stage in _V321_MANIFEST["stages"]:
            if tier not in stage["tiers"]:
                continue
            outputs = _v321_run_stage(stage, bundle, input_path, outputs, work, tier)
        ref = _V321_MANIFEST["final_reference"][tier]
        actual = outputs.get("files", {}).get(ref)
        if actual is None:
            # Directory-producing stage fallback.
            ref_dir = ref.rsplit("/", 1)[0]
            actual_dir = outputs.get("dirs", {}).get(ref_dir)
            if actual_dir:
                actual = str(_V321Path(actual_dir) / f"{tier}.json")
        if actual is None or not _V321Path(actual).is_file():
            raise RuntimeError(f"V32.1c final output missing for tier={tier} ref={ref}")
        # Parse before copying so malformed intermediate output cannot escape.
        parse_submission(load_json(_V321Path(actual)))
        target = _V321Path(output_path)
        target.parent.mkdir(parents=True, exist_ok=True)
        tmp = target.with_name(f".{target.name}.tmp-{_v321_os.getpid()}")
        tmp.write_bytes(_V321Path(actual).read_bytes()); tmp.chmod(0o644); _v321_os.replace(tmp, target)


def final_router_main(argv=None):
    from ossp_router.protocol import TIERS
    parser = _v321_argparse.ArgumentParser(prog="router-run")
    parser.add_argument("--input", type=_V321Path, required=True)
    parser.add_argument("--tier", choices=TIERS, required=True)
    parser.add_argument("--output", type=_V321Path, required=True)
    args = parser.parse_args(argv)
    try:
        _v321_generate(args.input, args.tier, args.output)
    except Exception as exc:
        print(f"오류: {exc}", file=_v321_sys.stderr); return 2
    print(f"OK: {args.tier} V32.1c exact-chain submission generated."); return 0
# END V32.1 EXACT FINAL ROUTER
